'use strict';

// cspell:ignore nbconvert nbformat unrenderable

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var fromMarkdown = require( '@stdlib/_tools/semantic-document/from-markdown' );
var cellID = require( './../lib/cell_id.js' );
var toIPYNB = require( './../lib' );


// FIXTURES //

var FIXTURES = resolve( __dirname, '..', '..', 'from-markdown', 'test', 'fixtures' );
var EXAMPLE = resolve( __dirname, '..', 'examples', 'fixtures', 'example.md.txt' );
var READ_OPTIONS = {
	'encoding': 'utf8'
};


// FUNCTIONS //

/**
* Returns a tutorial semantic document containing source.
*
* @private
* @param {string} source - JavaScript source
* @param {Array} [directives] - directive comments
* @returns {Object} semantic document
*/
function tutorial( source, directives ) {
	var markdown = [
		'# Example',
		'',
		'> Example summary.',
		''
	];

	if ( directives ) {
		markdown = markdown.concat( directives, [ '' ] );
	}
	markdown = markdown.concat([
		'```javascript',
		source,
		'```'
	]);
	return fromMarkdown( markdown.join( '\n' ), {
		'mode': 'strict',
		'profile': 'tutorial'
	});
}

/**
* Returns notebook cells of a specified type.
*
* @private
* @param {Object} notebook - notebook
* @param {string} type - cell type
* @returns {Array} cells
*/
function cells( notebook, type ) {
	return notebook.cells.filter( function filter( cell ) {
		return cell.cell_type === type;
	});
}

/**
* Removes explicit source envelopes from all semantic leaves.
*
* @private
* @param {Array} children - semantic children
* @returns {void}
*/
function removeEnvelopes( children ) {
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if ( children[ i ].children ) {
			removeEnvelopes( children[ i ].children );
		} else {
			delete children[ i ].source.envelope;
		}
	}
}

/**
* Returns a tutorial semantic document containing standalone media.
*
* @private
* @param {string} markdown - media Markdown
* @param {boolean} slices - boolean indicating whether to retain source slices
* @returns {Object} semantic document
*/
function media( markdown, slices ) {
	return fromMarkdown( '# Example\n\n> Example summary.\n\n'+markdown, {
		'includeSourceSlices': slices,
		'mode': 'strict',
		'profile': 'tutorial'
	});
}

/**
* Asserts that a module-map URL is rejected.
*
* @private
* @param {Object} t - Tape test context
* @param {Object} doc - semantic document
* @param {string} url - invalid URL
* @param {number} index - case index
* @returns {void}
*/
function assertInvalidURL( t, doc, url, index ) {
	t.throws( function invalidMapURLCase() {
		toIPYNB( doc, {
			'moduleMap': {
				'x': {
					'export': 'default',
					'mutable': false,
					'runtimes': [ 'worker' ],
					'url': url
				}
			}
		});
	}, TypeError, 'rejects malformed module-map URL '+index );
}

/**
* Tests whether a diagnostic reports unrenderable media.
*
* @private
* @param {Object} item - diagnostic
* @returns {boolean} boolean
*/
function isUnrenderableMedia( item ) {
	return item.code === 'semantic-document-to-ipynb/unrenderable-media';
}


// TESTS //

tape( 'main export is a function with a stringify helper', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof toIPYNB, 'function', 'main export is a function' );
	t.strictEqual( typeof toIPYNB.stringify, 'function', 'exposes stringify' );
	t.end();
});

tape( 'the function validates arguments and options', function test( t ) {
	var invalidURLs = [
		'https://x\n/injected.mjs',
		'https://x\r/injected.mjs',
		'https://x\u0000/injected.mjs',
		'https://x\u2028/injected.mjs',
		'https://?bad',
		'https://user:pass@example.com/x.mjs',
		'https://example.com\\x.mjs',
		'//example.com/x.mjs',
		'data:text/javascript,export default 1'
	];
	var doc = tutorial( '1;' );
	var i;

	t.throws( function invalidDocument() {
		toIPYNB( null );
	}, TypeError, 'rejects a non-document' );
	t.throws( function invalidMode() {
		toIPYNB( doc, {
			'mode': 'beep'
		});
	}, TypeError, 'rejects an invalid mode' );
	t.throws( function invalidTarget() {
		toIPYNB( doc, {
			'target': 'ijavascript'
		});
	}, TypeError, 'rejects an unsupported target' );
	t.throws( function invalidExcludedRoles() {
		toIPYNB( doc, {
			'excludeSectionRoles': 'c'
		});
	}, TypeError, 'rejects a non-array section-role exclusion' );
	t.throws( function invalidExcludedRole() {
		toIPYNB( doc, {
			'excludeSectionRoles': [ '' ]
		});
	}, TypeError, 'rejects an empty excluded section role' );
	t.throws( function duplicateExcludedRole() {
		toIPYNB( doc, {
			'excludeSectionRoles': [ 'c', 'c' ]
		});
	}, TypeError, 'rejects duplicate excluded section roles' );
	t.throws( function invalidMapURL() {
		toIPYNB( doc, {
			'moduleMap': {
				'x': {
					'export': 'default',
					'mutable': false,
					'runtimes': [ 'worker' ],
					'url': './x.mjs'
				}
			}
		});
	}, TypeError, 'rejects a relative module-map URL' );
	for ( i = 0; i < invalidURLs.length; i++ ) {
		assertInvalidURL( t, doc, invalidURLs[ i ], i );
	}
	t.end();
});

tape( 'the function converts a representative stdlib README deterministically', function test( t ) {
	var markdown;
	var second;
	var before;
	var first;
	var code;
	var doc;

	markdown = readFileSync( resolve( FIXTURES, 'readme', 'file.md.txt' ), READ_OPTIONS ); // eslint-disable-line n/no-sync
	doc = fromMarkdown( markdown, {
		'mode': 'strict',
		'profile': 'readme'
	});
	before = JSON.stringify( doc );
	first = toIPYNB( doc );
	second = toIPYNB( doc );
	code = cells( first, 'code' );

	t.deepEqual( first, second, 'returns deterministic output' );
	t.strictEqual( JSON.stringify( doc ), before, 'does not mutate the semantic document' );
	t.strictEqual( first.nbformat, 4, 'sets the major format' );
	t.strictEqual( first.nbformat_minor, 5, 'sets the minor format' );
	t.strictEqual( first.metadata.kernelspec.name, 'javascript-worker', 'targets the worker kernel by default' );
	t.strictEqual( first.metadata.title, 'abs', 'sets the notebook title' );
	t.strictEqual( code.length, 3, 'emits three executable JavaScript cells' );
	t.strictEqual(code[ 0 ].source.join( '' ), "import abs from 'https://cdn.jsdelivr.net/gh/stdlib-js/math-base-special-abs@esm/index.mjs';", 'lowers the setup binding to a standalone ESM URL');
	t.strictEqual( code[ 0 ].metadata.stdlib.pre_transform_source, "var abs = require( '@stdlib/math/base/special/abs' );", 'preserves pre-transform source' );
	t.strictEqual( code[ 0 ].metadata.stdlib.transforms[ 0 ].resolver_source, 'stdlib-esm-convention', 'records convention-based resolution' );
	t.ok( /^[a-zA-Z0-9-_]{1,64}$/.test( code[ 0 ].id ), 'emits a valid cell ID' );
	t.end();
});

