tape( 'the function excludes C section subtrees by default', function test( t ) {
	var completeSource;
	var omittedBreaks;
	var omissions;
	var notebook;
	var markdown;
	var complete;
	var source;
	var doc;

	markdown = readFileSync( EXAMPLE, READ_OPTIONS ); // eslint-disable-line n/no-sync
	doc = fromMarkdown( markdown, {
		'mode': 'strict',
		'profile': 'readme'
	});
	notebook = toIPYNB( doc );
	complete = toIPYNB( doc, {
		'excludeSectionRoles': []
	});

	source = notebook.cells.map( function cellSource( cell ) {
		return cell.source.join( '' );
	}).join( '\n' );
	completeSource = complete.cells.map( function completeCellSource( cell ) {
		return cell.source.join( '' );
	}).join( '\n' );
	omissions = notebook.metadata.stdlib.omissions;
	omittedBreaks = omissions.filter( function isRedundantBreak( item ) {
		return item.reason === 'redundant-thematic-break';
	});

	t.strictEqual( source.indexOf( '## C APIs' ), -1, 'omits the complete C subtree' );
	t.ok( source.indexOf( '## See Also' ) >= 0, 'retains useful related documentation' );
	t.strictEqual( ( source.match( /\* \* \*/g ) || [] ).length, 1, 'removes the redundant horizontal rule' );
	t.strictEqual( omissions.length, 2, 'records the omitted section and redundant rule' );
	t.strictEqual( omissions[ 1 ].role, 'c', 'records the excluded semantic role' );
	t.strictEqual( omittedBreaks.length, 1, 'records the thematic-break normalization' );
	t.strictEqual( omittedBreaks[ 0 ].type, 'thematicBreak', 'identifies the omitted semantic rule' );
	t.ok( completeSource.indexOf( '## C APIs' ) >= 0, 'an empty exclusion array retains C documentation' );
	t.strictEqual( complete.metadata.stdlib.omissions.length, 0, 'records no omissions when retaining every section' );
	t.end();
});

