tape( 'unsupported execution candidates follow the configured atomic fallback', function test( t ) {
	var notebook;
	var markdown;
	var doc = tutorial( "var thing = require( 'unknown-module' );" );
	var err;

	try {
		toIPYNB( doc );
	} catch ( error ) {
		err = error;
	}
	t.ok( err && err.notebook, 'strict default throws with a partial notebook' );
	t.ok( err.notebook.cells.length > 0, 'partial notebook retains completed narrative cells' );
	t.strictEqual( cells( err.notebook, 'code' ).length, 0, 'partial notebook excludes rejected code' );
	notebook = toIPYNB( doc, {
		'mode': 'permissive'
	});
	markdown = cells( notebook, 'markdown' );
	t.strictEqual( cells( notebook, 'code' ).length, 0, 'does not emit partially executable code' );
	t.strictEqual( markdown[ markdown.length-1 ].metadata.stdlib.disposition, 'display-only', 'uses a dedicated display-only cell' );
	t.deepEqual( markdown[ markdown.length-1 ].metadata.stdlib.failure_codes, [ 'semantic-document-to-ipynb/unsupported-module-specifier' ], 'records a stable failure code' );
	t.end();
});

