tape( 'standalone media requires exact source slices for lossless rendering', function test( t ) {
	var notebook;
	var source;
	var cases = [
		'![alt](x.png "title")',
		'![alt][img]\n\n[img]: x.png "title"',
		'![alt][missing]'
	];
	var doc;
	var err;
	var i;

	for ( i = 0; i < cases.length; i++ ) {
		notebook = toIPYNB( media( cases[ i ], true ) );
		source = cells( notebook, 'markdown' ).map( function cellSource( cell ) {
			return cell.source.join( '' );
		}).join( '\n' );
		t.ok( source.indexOf( cases[ i ].split( '\n' )[ 0 ] ) >= 0, 'uses exact media source slice '+i );
	}
	doc = media( cases[ 0 ], false );
	try {
		toIPYNB( doc );
	} catch ( error ) {
		err = error;
	}
	t.ok( err && err.notebook, 'strict mode rejects media without a source slice' );
	notebook = toIPYNB( doc, {
		'mode': 'permissive'
	});
	t.ok( notebook.cells[ 0 ].source.join( '' ).indexOf( 'Unsupported semantic content omitted' ) >= 0, 'permissive mode emits a visible placeholder' );
	source = notebook.metadata.stdlib.diagnostics.some( isUnrenderableMedia );
	t.ok( source, 'records the media fallback diagnostic' );
	t.end();
});

